import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class MerkleTree {
    private final List<String> transactions;
    private String rootHash;

    public MerkleTree(List<String> transactions) {
        this.transactions = transactions;
        this.rootHash = buildRoot(transactions);
    }

    private String sha256(String data) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(data.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private String buildRoot(List<String> nodes) {
        if (nodes.isEmpty()) return "";
        if (nodes.size() == 1) return sha256(nodes.get(0));

        List<String> parentLevel = new ArrayList<>();
        for (int i = 0; i < nodes.size(); i += 2) {
            String left = nodes.get(i);
            String right = (i + 1 < nodes.size()) ? nodes.get(i + 1) : left;
            parentLevel.add(sha256(left + right));
        }
        return buildRoot(parentLevel);
    }

    public String getRootHash() {
        return rootHash;
    }
}
